import{f as t,o as n,c as i,ar as r}from"./chunks/framework.HWAOx3Ef.js";const d="/Wahllokalsystem/fachlichesDatenmodell/vermutetesFachlichesDatenmodell_20241008.png",a="/Wahllokalsystem/fachlichesDatenmodell/Wahlkreiskarte_BTW2025.png",s="/Wahllokalsystem/fachlichesDatenmodell/Stimmkreiskarte_LTW_V1.jpg",w=JSON.parse('{"title":"Backend-Services","description":"","frontmatter":{},"headers":[],"relativePath":"services/backend-services/index.md","filePath":"services/backend-services/index.md"}'),l={name:"services/backend-services/index.md"};function h(o,e,g,m,c,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="backend-services" tabindex="-1">Backend-Services <a class="header-anchor" href="#backend-services" aria-label="Permalink to &quot;Backend-Services&quot;">​</a></h1><p>Für jeden Service gibt es eine separate Beschreibung zu dessen Aufgaben und Funktionen.</p><h2 id="fachliches-datenmodell" tabindex="-1">Fachliches Datenmodell <a class="header-anchor" href="#fachliches-datenmodell" aria-label="Permalink to &quot;Fachliches Datenmodell&quot;">​</a></h2><p>Das Datenmodell wurde unter Berücksichtigung der gesetzlichen Grundlagen verschiedener Wahlen und Abstimmungen sowie des örtlichen Kommunal- und Landeswahlrechts erstellt. Es verwendet bewusst übergreifende Begriffe, damit unterschiedliche Wahlarten in einer gemeinsamen Struktur abgebildet werden können.</p><p><img src="'+d+'" alt="Datenmodell:"><em><strong>Abbildung 1:</strong> Fachliches Datenmodell</em></p><h3 id="gegenstand-und-abgrenzung" tabindex="-1">Gegenstand und Abgrenzung <a class="header-anchor" href="#gegenstand-und-abgrenzung" aria-label="Permalink to &quot;Gegenstand und Abgrenzung&quot;">​</a></h3><p>Das Modell beschreibt die fachlichen Beziehungen zwischen Wahlterminen, einzelnen Wahlen oder Abstimmungen, organisatorischen Wahlbezirken, Stimmzettelgebieten sowie den auf dem Stimmzettel enthaltenen Wahlvorschlägen oder Abstimmungsvorlagen.</p><h3 id="erlauterung-der-bestehenden-entitaten" tabindex="-1">Erläuterung der bestehenden Entitäten <a class="header-anchor" href="#erlauterung-der-bestehenden-entitaten" aria-label="Permalink to &quot;Erläuterung der bestehenden Entitäten&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Entität</th><th>Bedeutung im fachlichen Datenmodell</th></tr></thead><tbody><tr><td><code>Wahltermin</code></td><td>Organisatorischer Rahmen für eine oder mehrere gleichzeitig oder organisatorisch gemeinsam durchgeführte Wahlen und Abstimmungen. Ein Wahltermin ist einem Datum zugeordnet. Die Ergebnisermittlung kann über den Wahltag hinaus fortgesetzt werden.</td></tr><tr><td><code>Wahl</code></td><td>Eine einzelne Wahl oder Abstimmung innerhalb eines Wahltermins, zum Beispiel Europawahl, Bundestagswahl, Stadtratswahl oder Bürgerentscheid. Die Wahlart wird als Eigenschaft dieser Entität geführt.</td></tr><tr><td><code>Stimmzettelgebiet</code></td><td>Gebiet, innerhalb dessen bei einer bestimmten Wahl oder Abstimmung Stimmzettel mit demselben Inhalt verwendet werden. Die konkrete räumliche Bedeutung hängt von der Wahlart ab.</td></tr><tr><td><code>Wahlbezirk</code></td><td>Allgemeine organisatorische Einheit, in der Stimmen abgegeben oder ausgezählt werden und für die ein Ergebnis ermittelt wird. Der Begriff wird im Modell als Oberbegriff für Stimm-/Wahlbezirke und Briefwahlbezirke verwendet.</td></tr><tr><td><code>Wahlvorstand</code></td><td>Für einen Wahlbezirk zuständiges Wahlorgan. Je nach Art des Wahlbezirks handelt es sich um einen Wahlvorstand oder einen Briefwahlvorstand.</td></tr><tr><td><code>Wahlvorstandsmitglied</code></td><td>Mitglied eines Wahlvorstands oder Briefwahlvorstands.</td></tr><tr><td><code>Vorschlag/Vorlage</code></td><td>Gemeinsame Oberklasse für Wahlvorschläge bei Wahlen und Abstimmungsvorlagen bei Volks- oder Bürgerentscheiden.</td></tr><tr><td><code>Wahlvorschlag</code></td><td>Zur Wahl stehender Vorschlag. Je nach Wahlart kann er beispielsweise eine Liste oder eine einzelne Person umfassen. Der Wahlvorschlag ist nicht zwingend mit einer Partei gleichzusetzen.</td></tr><tr><td><code>Kandidat</code></td><td>Bewerberin oder Bewerber innerhalb eines Wahlvorschlags. Im Modell wird zwischen Direktkandidaten und Listenkandidaten unterschieden.</td></tr><tr><td><code>Direktkandidat</code></td><td>Bewerberin oder Bewerber, die beziehungsweise der unmittelbar gewählt werden kann, zum Beispiel bei der Oberbürgermeisterwahl oder als Wahlkreisbewerbung bei der Bundestagswahl.</td></tr><tr><td><code>Listenkandidat</code></td><td>Bewerberin oder Bewerber innerhalb einer Liste, zum Beispiel bei der Stadtratswahl oder der Bezirksausschusswahl.</td></tr><tr><td><code>ReferendumVorlage</code></td><td>Bei einem Volksentscheid oder Bürgerentscheid zur Abstimmung gestellte Frage beziehungsweise Vorlage.</td></tr><tr><td><code>ReferendumOption</code></td><td>Zu einer Referendumsvorlage auswählbare Antwortmöglichkeit, regelmäßig „Ja“ oder „Nein“. Bei mehreren Vorlagen oder einer Stichfrage werden mehrere Vorlagen mit ihren jeweiligen Optionen abgebildet.</td></tr></tbody></table><h3 id="zuordnung-erganzender-organisatorischer-begriffe" tabindex="-1">Zuordnung ergänzender organisatorischer Begriffe <a class="header-anchor" href="#zuordnung-erganzender-organisatorischer-begriffe" aria-label="Permalink to &quot;Zuordnung ergänzender organisatorischer Begriffe&quot;">​</a></h3><p>Für die Beschreibung der praktischen Wahlorganisation sind weitere Begriffe erforderlich. Sie führen jedoch nicht zwingend zu zusätzlichen Entitäten im dargestellten Teilmodell. Die nachfolgende Zuordnung stellt klar, wie diese Begriffe einzuordnen sind.</p><table tabindex="0"><thead><tr><th>Begriff</th><th>Zuordnung zum bestehenden Modell</th><th>Erläuterung</th></tr></thead><tbody><tr><td>Stimm-/Wahlbezirk</td><td>Ausprägung der bestehenden Entität <code>Wahlbezirk</code></td><td>Organisatorische Einheit der Urnenwahl</td></tr><tr><td>Briefwahlbezirk</td><td>Ausprägung der bestehenden Entität <code>Wahlbezirk</code></td><td>Organisatorische Einheit der Briefwahl. Die Stimmen werden durch einen Briefwahlvorstand ermittelt</td></tr><tr><td>Stimmzettel</td><td>Aus <code>Wahl</code>, <code>Stimmzettelgebiet</code> und den zugeordneten <code>Vorschlägen oder Vorlagen</code> ableitbar</td><td>Eine eigenständige Entität ist erst erforderlich, wenn beispielsweise Layout, Versionierung, Druckfreigabe oder Bereitstellung als Datei fachlich verwaltet werden sollen.</td></tr><tr><td>Partei oder Wählergruppe</td><td>Mögliche Eigenschaft oder ergänzende Entität zum <code>Wahlvorschlag</code></td><td>Der Wahlvorschlag kann von einer Partei, einer Wählergruppe oder – abhängig von der Wahlart – von einer Einzelperson getragen werden.</td></tr></tbody></table><h3 id="zentraler-begriff-stimmzettelgebiet" tabindex="-1">Zentraler Begriff: Stimmzettelgebiet <a class="header-anchor" href="#zentraler-begriff-stimmzettelgebiet" aria-label="Permalink to &quot;Zentraler Begriff: Stimmzettelgebiet&quot;">​</a></h3><p><strong>Das <strong><code>Stimmzettelgebiet</code></strong> ist ein wahlartenübergreifender Begriff des fachlichen Datenmodells.</strong> Es bezeichnet das Gebiet, innerhalb dessen bei einer bestimmten Wahl oder Abstimmung Stimmzettel mit demselben Inhalt verwendet werden.</p><p>Die konkrete Bedeutung des Stimmzettelgebiets hängt von der Wahlart ab. Bei einer Bundestagswahl entspricht es beispielsweise dem Wahlkreis, bei einer Landtags- oder Bezirkswahl dem Stimmkreis. Bei anderen Wahlen kann das gesamte Stadtgebiet oder ein räumlich abgegrenzter Teil des Stadtgebiets ein Stimmzettelgebiet bilden.</p><p><strong>Ein Wahlbezirk wird für jede innerhalb eines Wahltermins stattfindende Wahl dem jeweils maßgeblichen Stimmzettelgebiet zugeordnet.</strong> Dadurch wird festgelegt, welcher Stimmzettelinhalt für die betreffende Wahl in diesem Stimmbezirk oder Briefwahlbezirk zu verwenden ist.</p><p><a href="https://stadt.muenchen.de/rathaus/politik/wahlen.html" target="_blank" rel="noreferrer">Quellen und mehr Informationen</a></p><h2 id="zuordnung-der-wahl-und-abstimmungsarten-im-uberblick" tabindex="-1">Zuordnung der Wahl- und Abstimmungsarten im Überblick <a class="header-anchor" href="#zuordnung-der-wahl-und-abstimmungsarten-im-uberblick" aria-label="Permalink to &quot;Zuordnung der Wahl- und Abstimmungsarten im Überblick&quot;">​</a></h2><p>Die folgenden Wahl- und Abstimmungsarten sind abzubilden. Wahlarten, die im Datenmodell nach demselben Grundmuster behandelt werden können, bleiben dennoch jeweils eigenständige Wahlen innerhalb eines Wahltermins.</p><table tabindex="0"><thead><tr><th>Wahl- oder Abstimmungsart</th><th>Stimmzettelgebiet</th><th>Abbildung im Datenmodell</th></tr></thead><tbody><tr><td>Europawahl</td><td>für München ein Stimmzettelgebiet</td><td>Wahlvorschläge mit Listenkandidaten</td></tr><tr><td>Bundestagswahl</td><td>Wahlkreis</td><td>Wahlvorschläge mit Direktkandidaten und Landeslisten</td></tr><tr><td>Landtagswahl</td><td>Stimmkreis</td><td>Wahlvorschläge mit Direkt- und Listenkandidaten</td></tr><tr><td>Bezirkswahl</td><td>Stimmkreis; strukturell wie Landtagswahl</td><td></td></tr><tr><td>Oberbürgermeisterwahl</td><td>gesamtes Stadtgebiet</td><td>Wahlvorschläge mit jeweils einer Direktkandidatur (Wahlvorschlag)</td></tr><tr><td>Stadtratswahl</td><td>gesamtes Stadtgebiet</td><td>Wahlvorschläge mit Listenkandidaten</td></tr><tr><td>Migrationsbeiratswahl</td><td>gesamtes Stadtgebiet; strukturell wie Stadtratswahl</td><td>Wahlvorschläge mit Listenkandidaten</td></tr><tr><td>Bezirksausschusswahl</td><td>je Stadtbezirk ein Stimmzettelgebiet; strukturell wie Stadtratswahl</td><td>Wahlvorschläge mit Listenkandidaten</td></tr><tr><td>Volksentscheid</td><td>Freistaat Bayern</td><td>Referendumsvorlagen mit Referendumoptionen</td></tr><tr><td>Bürgerentscheid</td><td>Gemeindegebiet, in München regelmäßig gesamtes Stadtgebiet</td><td>Referendumsvorlagen mit Referendumoptionen</td></tr></tbody></table><p><strong>Hinweis:</strong> „Identisch“ bedeutet in dieser Übersicht nicht, dass die Wahlen rechtlich gleich sind. Gemeint ist, dass sie im fachlichen Datenmodell nach demselben Strukturmuster abgebildet werden können.</p><h2 id="erlauterung-zu-einzelnen-wahl-und-abstimmungsarten" tabindex="-1">Erläuterung zu einzelnen Wahl- und Abstimmungsarten <a class="header-anchor" href="#erlauterung-zu-einzelnen-wahl-und-abstimmungsarten" aria-label="Permalink to &quot;Erläuterung zu einzelnen Wahl- und Abstimmungsarten&quot;">​</a></h2><h3 id="europawahl" tabindex="-1">Europawahl <a class="header-anchor" href="#europawahl" aria-label="Permalink to &quot;Europawahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Für die Organisation der Europawahl in München genügt ein Stimmzettelgebiet, da in sämtlichen Münchner Stimmbezirken und Briefwahlbezirken derselbe Stimmzettel verwendet wird. Bei der Europawahl können Parteien und sonstige politische Vereinigungen gemeinsame Listen für alle Länder oder Listen für einzelne Länder einreichen. Daher ist der Stimmzettel nicht zwingend bundesweit identisch. Für die Zuordnung innerhalb Münchens ist jedoch nur ein einheitliches Stimmzettelgebiet erforderlich.</p><p><strong>Abbildung im Modell:</strong> Die Europawahl wird als <code>Wahl</code> geführt. Die auf dem Stimmzettel enthaltenen Listen werden als <code>Wahlvorschläge</code> und die Bewerberinnen und Bewerber als <code>Listenkandidaten</code> abgebildet.</p><p><a href="https://stadt.muenchen.de/infos/europawahlen.html" target="_blank" rel="noreferrer">Mehr Informationen zur Europawahl</a></p><h3 id="bundestagswahl" tabindex="-1">Bundestagswahl <a class="header-anchor" href="#bundestagswahl" aria-label="Permalink to &quot;Bundestagswahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Bundestagswahl entspricht das Stimmzettelgebiet dem Wahlkreis. Der Stimmzettel unterscheidet sich insbesondere durch die im Wahlkreis antretenden Direktkandidatinnen und Direktkandidaten.</p><p>Bei der Bundestagswahl 2025 umfasste die Landeshauptstadt München vier Wahlkreise:</p><ul><li>216 - München-Nord</li><li>217 - München-Ost</li><li>218 - München-Süd</li><li>219 - München-West/Mitte</li></ul><p>Jeder Münchner Stimmbezirk und Briefwahlbezirk wird für die Bundestagswahl genau einem dieser Wahlkreise zugeordnet. Die geografische Zugehörigkeit zu einem der 25 Stadtbezirke ist dafür nicht maßgeblich.</p><p><strong>Abbildung im Modell:</strong> Die Wahlkreisvorschläge werden als <code>Wahlvorschläge</code> mit <code>Direktkandidaten</code> abgebildet. Daneben enthält der Stimmzettel die Landeslisten.</p><p><img src="'+a+'" alt="Wahlkreise in der Landeshauptstadt München"><em><strong>Abbildung 2:</strong> Wahlkreise zur Bundestagswahl in München (Beispiel Bundestagswahl 2025).</em></p><p><a href="https://stadt.muenchen.de/infos/bundestagswahlen.html" target="_blank" rel="noreferrer">Mehr Informationen zur Bundestagswahl</a></p><h3 id="landtagswahl-und-bezirkswahl" tabindex="-1">Landtagswahl und Bezirkswahl <a class="header-anchor" href="#landtagswahl-und-bezirkswahl" aria-label="Permalink to &quot;Landtagswahl und Bezirkswahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Landtagswahl entspricht das Stimmzettelgebiet dem Stimmkreis. Für die Bezirkswahl wird dieselbe räumliche Einteilung verwendet.</p><p>Landtagswahl und Bezirkswahl sind zwei eigenständige Wahlen. Sie werden im Datenmodell jeweils als eigene Wahl geführt und besitzen eigene Stimmzettelinhalte. Für beide Wahlen kann jedoch dieselbe räumliche Einteilung in Stimmkreise verwendet werden.</p><p>Das nachfolgende Beispiel zeigt die neun Münchner Stimmkreise der Landtagswahl 2023 (101 bis 109). Innerhalb eines Stimmkreises wird für die jeweilige Wahl dasselbe Stimmzettelpaar verwendet. Die Zugehörigkeit zu einem Stadtbezirk ist hierfür nicht maßgeblich.</p><p><strong>Abbildung im Modell:</strong> <code>Wahlvorschläge</code> enthalten <code>Direkt-</code> und <code>Listenkandidaten</code>. Landtagswahl und Bezirkswahl werden als getrennte <code>Wahlen</code> desselben <code>Wahltermins</code> geführt.</p><p><img src="'+s+'" alt="Stimmkreiskarte in der Landeshauptstadt München"><em><strong>Abbildung 3:</strong> Stimmkreise zur Landtagswahl in München (Beispiel Landtagswahl 2023).</em></p><p>Für jede Wahl gibt es 2 Stimmzettel (klein – mit Direktkandidatur; groß – mit Listenkandidaturen). Jeder Wahlvorschlag hat Listenkandidaturen, aber nicht immer eine Direktkandidatur.</p><p><a href="https://stadt.muenchen.de/infos/landtagswahlen-und-bezirkswahlen-teil-ii.html" target="_blank" rel="noreferrer">Mehr Informationen zur Landtagswahl.</a></p><h3 id="oberburgermeisterwahl" tabindex="-1">Oberbürgermeisterwahl <a class="header-anchor" href="#oberburgermeisterwahl" aria-label="Permalink to &quot;Oberbürgermeisterwahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Oberbürgermeisterwahl ist das gesamte Gebiet der Landeshauptstadt München ein Stimmzettelgebiet. In allen Münchner Stimmbezirken und Briefwahlbezirken wird derselbe Stimmzettel verwendet.</p><p><strong>Abbildung im Modell:</strong> Jeder zugelassene <code>Wahlvorschlag</code> umfasst eine unmittelbar wählbare Bewerberin oder einen unmittelbar wählbaren Bewerber. Diese Person wird als <code>Direktkandidat</code> abgebildet.</p><p>Eine erforderliche Stichwahl findet an einem weiteren Datum statt und wird daher als eigener <code>Wahltermin</code> mit einer eigenen <code>Wahl</code> geführt.</p><h3 id="stadtratswahl" tabindex="-1">Stadtratswahl <a class="header-anchor" href="#stadtratswahl" aria-label="Permalink to &quot;Stadtratswahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Stadtratswahl ist das gesamte Gebiet der Landeshauptstadt München ein Stimmzettelgebiet. Der Stimmzettel ist in allen Münchner Stimmbezirken und Briefwahlbezirken identisch.</p><p><strong>Abbildung im Modell:</strong> Die zur Wahl stehenden Listen werden als <code>Wahlvorschläge</code> und die darauf geführten Bewerberinnen und Bewerber als <code>Listenkandidaten</code> abgebildet. Die besonderen Regeln zur Stimmenvergabe, beispielsweise Kumulieren, Panaschieren oder Streichen, betreffen die Auswertung des Stimmzettels, ändern aber nicht die grundlegende Struktur des Datenmodells.</p><h3 id="migrationsbeiratswahl" tabindex="-1">Migrationsbeiratswahl <a class="header-anchor" href="#migrationsbeiratswahl" aria-label="Permalink to &quot;Migrationsbeiratswahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Migrationsbeiratswahl ist das gesamte Gebiet der Landeshauptstadt München ein Stimmzettelgebiet.</p><p><strong>Abbildung im Modell:</strong> Die Migrationsbeiratswahl wird strukturell wie die Stadtratswahl abgebildet: <code>Wahlvorschläge</code> enthalten <code>Listenkandidaten</code>. Sie bleibt jedoch eine eigenständige <code>Wahl</code>. Da sich der Kreis der Wahlberechtigten von anderen Wahlen unterscheidet, kann sie in einem gesonderten <code>Wahltermin</code> mit eigenen <code>Wahlbezirken</code> organisiert werden.</p><h3 id="bezirksausschusswahl" tabindex="-1">Bezirksausschusswahl <a class="header-anchor" href="#bezirksausschusswahl" aria-label="Permalink to &quot;Bezirksausschusswahl&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei der Bezirksausschusswahl entspricht das Stimmzettelgebiet dem jeweiligen Stadtbezirk. München besitzt 25 Stadtbezirke und damit für die Bezirksausschusswahl 25 unterschiedliche Stimmzettelgebiete.</p><p><strong>Abbildung im Modell:</strong> Die Bezirksausschusswahl wird strukturell wie die Stadtratswahl abgebildet: <code>Wahlvorschläge</code> enthalten <code>Listenkandidaten</code>. Anders als bei der Stadtratswahl unterscheiden sich die Stimmzettelinhalte jedoch nach dem Stadtbezirk.</p><p>Bei einer gleichzeitig stattfindenden Kommunalwahl ist ein <code>Wahlbezirk</code> daher für die Oberbürgermeisterwahl und die Stadtratswahl jeweils einem stadtweiten <code>Stimmzettelgebiet</code>, für die Bezirksausschusswahl aber dem <code>Stimmzettelgebiet</code> seines Stadtbezirks zugeordnet.</p><h3 id="volksentscheid" tabindex="-1">Volksentscheid <a class="header-anchor" href="#volksentscheid" aria-label="Permalink to &quot;Volksentscheid&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei einem bayerischen Volksentscheid ist der Freistaat Bayern das Stimmzettelgebiet. Für die Durchführung in München wird daher ein einheitlicher Stimmzettelinhalt verwendet.</p><p><strong>Abbildung im Modell:</strong> Die zur Abstimmung gestellte Frage oder Vorlage wird als <code>ReferendumVorlage</code> und die auswählbaren Antworten werden als <code>ReferendumOptionen</code> abgebildet. Finden mehrere Abstimmungen gleichzeitig statt oder ist eine Stichfrage erforderlich, werden mehrere <code>Vorlagen</code> geführt.</p><h3 id="burgerentscheid" tabindex="-1">Bürgerentscheid <a class="header-anchor" href="#burgerentscheid" aria-label="Permalink to &quot;Bürgerentscheid&quot;">​</a></h3><p><strong><code>Stimmzettelgebiet</code></strong> – Bei einem Bürgerentscheid ist grundsätzlich das Gebiet der Gemeinde das Stimmzettelgebiet. Für einen Bürgerentscheid der Landeshauptstadt München ist dies regelmäßig das gesamte Stadtgebiet.</p><p><strong>Abbildung im Modell:</strong> Die Fragestellung wird als <code>ReferendumVorlage</code> und die Antwortmöglichkeiten werden als <code>ReferendumOptionen</code> abgebildet. Bei mehreren Bürgerentscheiden oder einer Stichfrage werden mehrere <code>Vorlagen</code> geführt.</p><p>Ein Bürgerentscheid kann gemeinsam mit einer Wahl durchgeführt werden. Wenn die organisatorische Durchführung gemeinsam erfolgt, kann er demselben <code>Wahltermin</code> zugeordnet werden.</p><h2 id="beispiele-fur-die-zuordnung-bei-gleichzeitig-stattfindenden-wahlen" tabindex="-1">Beispiele für die Zuordnung bei gleichzeitig stattfindenden Wahlen <a class="header-anchor" href="#beispiele-fur-die-zuordnung-bei-gleichzeitig-stattfindenden-wahlen" aria-label="Permalink to &quot;Beispiele für die Zuordnung bei gleichzeitig stattfindenden Wahlen&quot;">​</a></h2><p>Die besondere Stärke des Modells liegt darin, dass ein Wahlbezirk innerhalb eines Wahltermins für unterschiedliche Wahlen unterschiedlichen Stimmzettelgebieten zugeordnet werden kann. Die folgenden Beispiele verdeutlichen dies.</p><table tabindex="0"><thead><tr><th>Beispiel</th><th>Zuordnung im fachlichen Datenmodell</th></tr></thead><tbody><tr><td>Kommunalwahl in München</td><td>Ein Stimmbezirk gehört bei der Oberbürgermeisterwahl zum stadtweiten <code>Stimmzettelgebiet</code> <em><strong>München</strong></em>, bei der Stadtratswahl ebenfalls zum stadtweiten <code>Stimmzettelgebiet</code> <em><strong>München</strong></em> und bei der Bezirksausschusswahl zum <code>Stimmzettelgebiet</code> des jeweiligen Stadtbezirks.</td></tr><tr><td>Bundestagswahl und Bürgerentscheid am selben Datum</td><td>Ein Stimmbezirk kann bei der Bundestagswahl dem maßgeblichen Bundestagswahlkreis und beim Bürgerentscheid zugleich dem stadtweiten <code>Stimmzettelgebiet</code> <em><strong>München</strong></em> zugeordnet werden. Werden beide Abstimmungen organisatorisch gemeinsam durchgeführt, können sie demselben <code>Wahltermin</code> angehören.</td></tr><tr><td>Landtagswahl und Bezirkswahl</td><td>Beide Wahlen finden regelmäßig gemeinsam statt und verwenden dieselbe räumliche Einteilung in Stimmkreise. Im Modell werden dennoch zwei <code>Wahlen</code> mit jeweils eigenen <code>Stimmzettelgebieten</code>, <code>Wahlvorschlägen</code> und Stimmzettelinhalten geführt.</td></tr><tr><td>Migrationsbeiratswahl</td><td>Aufgrund des abweichenden Kreises der Wahlberechtigten kann die Migrationsbeiratswahl in einem gesonderten <code>Wahltermin</code> mit eigenen <code>Wahlbezirken</code> organisiert werden. Strukturell bleibt sie wie die Stadtratswahl abbildbar.</td></tr></tbody></table>',66)])])}const z=t(l,[["render",h]]);export{w as __pageData,z as default};
